//! Regenerating instead of bouncing: a repo whose main has `.fleetd/regenerate.json` gets a PR that conflicts only in
//! generated files rebased and regenerated by the train on its node's checkout, and an early migration renamed; any
//! other conflict, a node that takes no agent work, or commands that give different files each run still send it back.
use super::*;

/// `gen/all.txt` is every `src/*.txt` in order, as the repo's own command makes it.
const MAKE: &str = "mkdir -p gen && cat src/*.txt > gen/all.txt";

/// A kit whose main says how `gen/` is made, with the repo's checkout on its node cloned from the origin.
fn regen_kit(run: &str) -> Kit {
    let kit = Kit::new();
    let config =
        json!({ "generated": ["gen/"], "run": [run], "migrations": "migrations/" }).to_string();
    kit.commit(
        "main",
        &[
            (".fleetd/regenerate.json", Some(&config)),
            ("src/a.txt", Some("a\n")),
            ("gen/all.txt", Some("a\n")),
            ("migrations/202601010000_first.sql", Some("-- first\n")),
        ],
        None,
    );
    let checkout = kit._dir.0.join("node-checkout");
    git(
        &kit._dir.0,
        &[
            "clone",
            "-q",
            kit.gh.origin.to_str().unwrap(),
            checkout.to_str().unwrap(),
        ],
    );
    *kit.host.checkout.lock().unwrap() = Some(checkout);
    kit
}

/// PR 7 adds `src/b.txt` with its `gen/all.txt`; then main adds `src/c.txt` with its own: they conflict only there.
async fn generated_conflict(kit: &Kit, also: &[(&str, Option<&str>)]) -> ChangeId {
    let mut files = vec![("src/b.txt", Some("b\n")), ("gen/all.txt", Some("a\nb\n"))];
    files.extend_from_slice(also);
    let pr = kit.open_pr(7, "add-b", &files);
    let (_, change) = kit.author_task(Some(&pr)).await;
    kit.commit(
        "main",
        &[("src/c.txt", Some("c\n")), ("gen/all.txt", Some("a\nc\n"))],
        None,
    );
    change
}

async fn until_merged(kit: &Kit, change: &ChangeId) {
    for _ in 0..6 {
        if kit.get(change).state == ChangeState::Merged {
            return;
        }
        kit.train.step(REPO).await;
        kit.train.regenerations_done().await;
    }
    panic!("not merged: {:?}", kit.get(change));
}

#[tokio::test(flavor = "multi_thread")]
async fn a_conflict_only_in_generated_files_is_regenerated_on_the_node_and_merges() {
    let kit = regen_kit(MAKE);
    let change = generated_conflict(&kit, &[]).await;
    let head = kit.head_of("add-b");

    assert!(kit.train.step(REPO).await);
    // It keeps its place while the train regenerates it, and nobody is told to rebase.
    let waiting = kit.get(&change);
    assert_eq!(waiting.state, ChangeState::Ready);
    assert!(kit.host.events_of("change.needs_rebase").is_empty());
    kit.train.regenerations_done().await;

    // Rebased onto main, gen/ made again from both sides, as the train's own commit.
    assert_ne!(kit.head_of("add-b"), head);
    assert_eq!(
        kit.file_on("add-b", "gen/all.txt").as_deref(),
        Some("a\nb\nc")
    );
    assert_eq!(kit.file_on("add-b", "src/c.txt").as_deref(), Some("c"));
    let subject = git(&kit.gh.origin, &["log", "-1", "--format=%s", "add-b"]);
    assert!(
        subject.starts_with("Regenerate the generated files on main"),
        "{subject}"
    );
    let note = kit.get(&change).last_error.unwrap_or_default();
    assert!(
        note.contains("regenerated its generated files and pushed"),
        "{note}"
    );
    // Fetch and push are git of their own; only the script between them runs the repo's commands.
    assert_eq!(
        *kit.host.node_runs.lock().unwrap(),
        ["git fetch", "sh -c", "git push"]
    );

    // The new head is reviewed again (its patch changed), tested and merged.
    until_merged(&kit, &change).await;
    assert_eq!(kit.main_file("gen/all.txt").as_deref(), Some("a\nb\nc"));
    assert!(kit.host.events_of("change.needs_rebase").is_empty());
    assert!(kit.host.sends.lock().unwrap().is_empty());
}

#[tokio::test(flavor = "multi_thread")]
async fn a_conflict_in_a_source_file_still_goes_back_to_its_author() {
    let kit = regen_kit(MAKE);
    let change =
        generated_conflict(&kit, &[("a.txt", Some(&a_with(&[(5, "author's line 5")])))]).await;
    kit.commit(
        "main",
        &[("a.txt", Some(&a_with(&[(5, "main's line 5")])))],
        None,
    );
    let head = kit.head_of("add-b");

    assert!(kit.train.step(REPO).await);
    kit.train.regenerations_done().await;

    let parked = kit.get(&change);
    assert_eq!(parked.state, ChangeState::NeedsRebase);
    let why = parked.last_error.unwrap_or_default();
    assert!(
        why.starts_with("conflicts with main, and the train could not regenerate")
            && why.contains("a.txt, which is not a generated file"),
        "{why}"
    );
    // Nothing was pushed, and its author hears why.
    assert_eq!(kit.head_of("add-b"), head);
    let (to, message) = kit.host.sends.lock().unwrap().last().cloned().unwrap();
    assert_eq!(to, "T1");
    assert!(
        message.contains("a.txt, which is not a generated file"),
        "{message}"
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn a_migration_that_sorts_before_mains_newest_gets_a_fresh_stamp() {
    let kit = regen_kit(MAKE);
    let pr = kit.open_pr(
        7,
        "migrate",
        &[("migrations/202605010000_mine.sql", Some("-- mine\n"))],
    );
    let (_, change) = kit.author_task(Some(&pr)).await;
    kit.commit(
        "main",
        &[("migrations/202610270000_theirs.sql", Some("-- theirs\n"))],
        None,
    );

    kit.train.step(REPO).await;
    kit.train.regenerations_done().await;

    let names = git(
        &kit.gh.origin,
        &["ls-tree", "--name-only", "migrate:migrations/"],
    );
    let mine: Vec<&str> = names.lines().filter(|n| n.ends_with("_mine.sql")).collect();
    assert_eq!(mine.len(), 1, "{names}");
    let stamp: u64 = mine[0].split('_').next().unwrap().parse().unwrap();
    assert!(stamp > 202610270000, "{}", mine[0]);
    assert_eq!(mine[0].len(), "202610270000_mine.sql".len());

    until_merged(&kit, &change).await;
    assert_eq!(
        kit.main_file(&format!("migrations/{}", mine[0])).as_deref(),
        Some("-- mine")
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn with_no_node_to_take_the_work_a_generated_conflict_goes_back_as_before() {
    let kit = regen_kit(MAKE);
    *kit.host.node_refusal.lock().unwrap() =
        Some("devbox, where the repo's checkout is, takes no agent work".into());
    let change = generated_conflict(&kit, &[]).await;

    assert!(kit.train.step(REPO).await);
    kit.train.regenerations_done().await;

    let parked = kit.get(&change);
    assert_eq!(parked.state, ChangeState::NeedsRebase);
    assert!(
        parked
            .last_error
            .unwrap_or_default()
            .ends_with("devbox, where the repo's checkout is, takes no agent work")
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn commands_that_make_different_files_each_run_are_not_trusted() {
    let kit = regen_kit("mkdir -p gen && cat src/*.txt > gen/all.txt && date +%s%N >> gen/all.txt");
    let change = generated_conflict(&kit, &[]).await;
    let head = kit.head_of("add-b");

    assert!(kit.train.step(REPO).await);
    kit.train.regenerations_done().await;

    let parked = kit.get(&change);
    assert_eq!(parked.state, ChangeState::NeedsRebase);
    let why = parked.last_error.unwrap_or_default();
    assert!(why.contains("not deterministic"), "{why}");
    assert_eq!(kit.head_of("add-b"), head);
}

/// GitHub finding a PR in line conflicting sends it to the same regeneration, before the train ever takes it (D191).
#[tokio::test(flavor = "multi_thread")]
async fn a_pr_github_finds_conflicting_in_generated_files_is_regenerated_where_it_waits() {
    let kit = regen_kit(MAKE);
    let change = generated_conflict(&kit, &[]).await;
    set_mergeable(&kit, 7, Some(false));
    let head = kit.head_of("add-b");

    kit.train.step(REPO).await;
    kit.train.regenerations_done().await;

    assert!(kit.host.events_of("change.needs_rebase").is_empty());
    assert_ne!(kit.head_of("add-b"), head);
    assert_eq!(
        kit.file_on("add-b", "gen/all.txt").as_deref(),
        Some("a\nb\nc")
    );
    set_mergeable(&kit, 7, None);
    until_merged(&kit, &change).await;
}
